import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    s = input_data[1]
    m = len(s)
    MOD = 1000000007

    # Precompute KMP transition table
    # pi[i] is the length of the longest proper prefix of s[0...i] 
    # that is also a suffix of s[0...i]
    pi = [0] * m
    for i in range(1, m):
        j = pi[i-1]
        while j > 0 and s[i] != s[j]:
            j = pi[j-1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j

    # trans[state][char] -> new_state
    # state ranges from 0 to m-1 (m is the absorbing state)
    # char: 0 for '(', 1 for ')'
    trans = [[0] * 2 for _ in range(m)]

    for state in range(m):
        for char_code in range(2):
            char = '(' if char_code == 0 else ')'
            j = state
            while j > 0 and char != s[j]:
                j = pi[j-1]
            if char == s[j]:
                j += 1
            trans[state][char_code] = j

    # DP state: dp[length][balance][kmp_state]
    # length: 0 to 2n
    # balance: 0 to n (cannot exceed n, cannot go below 0)
    # kmp_state: 0 to m (m is absorbing)

    # We can optimize space by only keeping current and next length layers
    # But given n <= 100, 2n <= 200, m <= 200, a full 3D array is fine: 200 * 101 * 201 ~ 4 million ints
    # Let's use a dictionary or list of lists for flexibility, but a 3D list is faster.

    # Dimensions: (2n + 1) x (n + 1) x (m + 1)
    # Initialize with 0
    dp = [[[0] * (m + 1) for _ in range(n + 1)] for _ in range(2 * n + 1)]

    dp[0][0][0] = 1

    for length in range(2 * n):
        for balance in range(n + 1):
            for state in range(m + 1):
                count = dp[length][balance][state]
                if count == 0:
                    continue

                # Try adding '('
                if balance + 1 <= n:
                    new_balance = balance + 1
                    if state < m:
                        new_state = trans[state][0]
                    else:
                        new_state = m

                    if new_state == m:
                        dp[length + 1][new_balance][m] = (dp[length + 1][new_balance][m] + count) % MOD
                    else:
                        dp[length + 1][new_balance][new_state] = (dp[length + 1][new_balance][new_state] + count) % MOD

                # Try adding ')'
                if balance - 1 >= 0:
                    new_balance = balance - 1
                    if state < m:
                        new_state = trans[state][1]
                    else:
                        new_state = m

                    if new_state == m:
                        dp[length + 1][new_balance][m] = (dp[length + 1][new_balance][m] + count) % MOD
                    else:
                        dp[length + 1][new_balance][new_state] = (dp[length + 1][new_balance][new_state] + count) % MOD

    # The answer is the number of sequences of length 2n with balance 0 and kmp_state m
    ans = dp[2 * n][0][m]
    print(ans)

if __name__ == "__main__":
    solve()
